const fmtDate=d=>new Date(d+'T12:00:00').toLocaleDateString(lang==='de'?'de-DE':'en-GB',{day:'numeric',month:'long',year:'numeric'});
let lang='en';try{lang=localStorage.getItem('gaia_lang')==='de'?'de':'en'}catch(e){}let activeTab='people';let activeUse='business';const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const pad=i=>String(i+1).padStart(2,'0');
function ecoSvg(c){const C={people:[500,262],processes:[395,432],solutions:[605,432]},T={people:[500,238],processes:[365,446],solutions:[635,446]},G={people:'gP',processes:'gR',solutions:'gS'},names={people:c.tabPeople,processes:c.tabProcesses,solutions:c.tabSolutions};
const caps=[[100,175,268,167],[90,370,200,360],[100,560,276,560],[900,175,732,167],[910,370,800,360],[900,560,724,560]];
const order=['processes','solutions','people'];
return `<svg viewBox="0 0 1000 720" data-active="${activeTab}" role="img" aria-label="${esc(c.ecoTitle.replace(/<[^>]+>/g,' '))}"><defs>
<radialGradient id="gP" cx="40%" cy="30%"><stop offset="0" stop-color="#3d6f8f"/><stop offset="1" stop-color="#14324b"/></radialGradient>
<radialGradient id="gR" cx="35%" cy="40%"><stop offset="0" stop-color="#4c9a97"/><stop offset="1" stop-color="#1c5a63"/></radialGradient>
<radialGradient id="gS" cx="60%" cy="40%"><stop offset="0" stop-color="#4d86ad"/><stop offset="1" stop-color="#1a4767"/></radialGradient>
<radialGradient id="gGlow"><stop offset="0" stop-color="#fff" stop-opacity="1"/><stop offset=".35" stop-color="#f3e2b8" stop-opacity=".7"/><stop offset="1" stop-color="#f3e2b8" stop-opacity="0"/></radialGradient>
<radialGradient id="gRing"><stop offset=".7" stop-color="#f4f9f8"/><stop offset="1" stop-color="#e2efee"/></radialGradient>
<path id="ringArc" d="M190 247 A330 330 0 0 1 810 247"/></defs>
<circle class="eco-ring-bg" cx="500" cy="360" r="300" fill="url(#gRing)"/>
<circle class="eco-ring" data-k="space" cx="500" cy="360" r="300"/>
<circle class="eco-orbit" cx="500" cy="360" r="262"/>
<text class="eco-ring-text"><textPath href="#ringArc" startOffset="50%" text-anchor="middle">${esc(c.ecoRing)}</textPath></text>
<g class="eco-spin"><circle cx="800" cy="360" r="7"/><circle cx="350" cy="100" r="5"/><circle cx="350" cy="620" r="6"/></g>
${caps.map((p,i)=>`<g class="eco-cap" style="--i:${i}"><path d="M${p[0]<500?p[0]+70:p[0]-70} ${p[1]-6} L${p[2]} ${p[3]}"/><circle cx="${p[2]}" cy="${p[3]}" r="6"/>${c.ecoCaps[i].split('|').map((t,j)=>`<text x="${p[0]}" y="${p[1]+j*21}" text-anchor="middle">${esc(t)}</text>`).join('')}</g>`).join('')}
${order.map((k,i)=>`<g class="eco-c" data-k="${k}" style="--i:${['people','processes','solutions'].indexOf(k)}" tabindex="0" role="button" aria-label="${esc(names[k])}"><circle cx="${C[k][0]}" cy="${C[k][1]}" r="140" fill="url(#${G[k]})"/></g>`).join('')}
<circle class="eco-glow" cx="500" cy="372" r="46" fill="url(#gGlow)"/>
<g class="eco-labels">${order.map(k=>`<g class="eco-l" data-k="${k}"><text class="eco-name" x="${T[k][0]}" y="${T[k][1]}" text-anchor="middle">${esc(names[k])}</text><path d="M${T[k][0]-22} ${T[k][1]+16} h44"/>${c.ecoKw[k].map((w,j)=>`<text class="eco-kw" x="${T[k][0]}" y="${T[k][1]+38+j*20}" text-anchor="middle">${esc(w.toUpperCase())}</text>`).join('')}</g>`).join('')}</g></svg><p class="eco-hint">${esc(c.ecoHint)}</p>`}
document.addEventListener('click',e=>{const g=e.target.closest&&e.target.closest('#ecoDiagram [data-k]');if(g){const b=document.querySelector('.eco-tab[data-tab="'+g.dataset.k+'"]');if(b)b.click()}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches&&e.target.matches('#ecoDiagram .eco-c')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}))}});
function aiNet(k){let seed=k*9301+49297;const r=()=>(seed=(seed*9301+49297)%233280)/233280;const W=400,H=225,n=[];for(let i=0;i<13;i++)n.push([20+r()*(W-40),18+r()*(H-36)]);const e=[];n.forEach((p,i)=>n.forEach((q,j)=>{if(j>i&&Math.hypot(p[0]-q[0],p[1]-q[1])<130)e.push([p,q])}));const f=x=>x.toFixed(1);let out=`<svg class="xp-net" viewBox="0 0 ${W} ${H}" preserveAspectRatio="xMidYMid slice" aria-hidden="true"><defs><linearGradient id="xs${k}" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#d1a654" stop-opacity="0"/><stop offset=".85" stop-color="#d1a654" stop-opacity=".35"/><stop offset="1" stop-color="#f3d58f" stop-opacity=".9"/></linearGradient></defs>`;out+=e.map(([p,q])=>`<line x1="${f(p[0])}" y1="${f(p[1])}" x2="${f(q[0])}" y2="${f(q[1])}"/>`).join('');out+=e.filter((x,i)=>i%2===0).slice(0,7).map(([p,q],i)=>`<circle class="xp-pulse" r="2.6"><animateMotion dur="${(2.2+((i*0.7)%2)).toFixed(1)}s" begin="${(i*0.45).toFixed(2)}s" repeatCount="indefinite" path="M${f(p[0])} ${f(p[1])}L${f(q[0])} ${f(q[1])}"/></circle>`).join('');out+=n.map((p,i)=>`<circle class="xp-node" style="--d:${(i*0.37%3).toFixed(2)}s" cx="${f(p[0])}" cy="${f(p[1])}" r="${i%4===0?4.2:2.6}"/>`).join('');out+=`<rect class="xp-scan" x="0" y="-70" width="${W}" height="70" fill="url(#xs${k})"/><path class="xp-brk" d="M12 34V12h22M${W-34} 12h22v22M12 ${H-34}v22h22M${W-34} ${H-12}h22v-22"/></svg>`;return out}
function render(){let c=content[lang];document.documentElement.lang=lang;document.title=lang==='en'?'GAIA PATH — Better decisions with AI':'GAIA PATH — Bessere Entscheidungen mit KI';document.querySelectorAll('[data-i]').forEach(n=>{n.innerHTML=c[n.dataset.i]});document.querySelectorAll('[data-placeholder-i]').forEach(n=>n.placeholder=c[n.dataset.placeholderI]);document.querySelectorAll('#language [data-lang]').forEach(b=>{const on=b.dataset.lang===lang;b.classList.toggle('on',on);b.setAttribute('aria-pressed',String(on))});document.querySelector('#founderEditorialLink').href='founder.html?lang='+lang;document.querySelector('#pubGrid').innerHTML=pubs.map((p,i)=>`<a class="pub-card" href="${esc(p[2])}" target="_blank" rel="noopener"><span class="pub-no">${pad(i)}</span><small>${esc(fmtDate(p[1]))}</small><strong>${esc(p[0])}</strong><span class="pub-more">${c.pubRead} ↗</span></a>`).join('')+`<a class="pub-card pub-all" href="https://www.linkedin.com/in/leonidas-shariati/recent-activity/articles/" target="_blank" rel="noopener"><span class="pub-no">in</span><strong>${c.pubAll}</strong><small>${c.pubAllText}</small><span class="pub-more">↗</span></a>`;
document.querySelector('#problemGrid').innerHTML=c.problems.map((p,i)=>`<div class="problem-card"><span class="step-number">${pad(i)}</span><h3>${esc(p[0])}</h3><p>${esc(p[1])}</p></div>`).join('');
document.querySelector('#steps').innerHTML=c.steps.map((s,i)=>`<div class="step"><span class="step-number">${pad(i)}</span><h3>${esc(s[0])}</h3><p>${esc(s[1])}</p></div>`).join('');
const B=c.brief,li=t=>t.split('|').map(x=>`<li>${esc(x)}</li>`).join('');document.querySelector('#briefDoc').innerHTML=`<div class="brief-head"><span class="brief-tag">${esc(B.tag)}</span><h3>${esc(B.q)}</h3><dl>${B.meta.map(m=>`<div><dt>${esc(m[0])}</dt><dd>${esc(m[1])}</dd></div>`).join('')}</dl></div><div class="brief-table-wrap"><table class="brief-table"><thead><tr>${B.optHead.map(x=>`<th>${esc(x)}</th>`).join('')}</tr></thead><tbody>${B.opts.map(o=>`<tr><td><b class="brief-opt">${esc(o[0])}</b> ${esc(o[1])}</td><td data-l="${esc(B.optHead[1])}">${esc(o[2])}</td><td data-l="${esc(B.optHead[2])}">${esc(o[3])}</td><td data-l="${esc(B.optHead[3])}">${esc(o[4])}</td></tr>`).join('')}</tbody></table></div><div class="brief-blocks">${B.blocks.map(b=>`<div class="brief-block"><span class="brief-cap">${esc(b[1])}</span><h4>${esc(b[0])}</h4><ul>${li(b[2])}</ul></div>`).join('')}</div><p class="brief-foot"><span class="brief-dot" aria-hidden="true"></span>${esc(B.foot)} <strong>${esc(B.footStrong)}</strong></p>`;
document.querySelector('#useList').innerHTML=c.uses[activeUse].map((a,i)=>`<div class="area-row"><span class="number">${pad(i)}</span><h3>${esc(a[0])}</h3><p>${esc(a[1])}</p><span class="arrow">↗</span></div>`).join('');
document.querySelector('#ecoDiagram').innerHTML=ecoSvg(c);if(window.filmRender)filmRender(c);document.querySelector('#tabPanel').innerHTML=`<h3>${esc(c.ecosystem[activeTab][0])}</h3><p>${esc(c.ecosystem[activeTab][1])}</p>`;
document.querySelector('#serviceGrid').innerHTML=c.services.map(s=>`<article class="service-card" id="svc-${s[0]}"><div class="service-photo service-photo-${s[0]}"></div><div class="service-num">${s[0]} / 04</div><h3>${esc(s[1])}</h3><p>${esc(s[2])}</p><div class="service-result">${esc(s[3])} →</div></article>`).join('');
document.querySelector('#xpGrid').innerHTML=c.xpAreas.map((a,i)=>`<article class="xp-card" style="--i:${i}"><div class="xp-art"><img src="assets/xp-${i+1}.jpg" alt="" loading="lazy">${aiNet(i)}<span class="xp-live"><i></i>${esc(c.xpLive)}</span><span class="xp-hud" data-hud="${i}">${esc(c.xpHud[i][0])}</span></div><div class="xp-top"><span class="xp-num">${pad(i)}</span><span class="xp-badge">${esc(c.xpBadge)}</span></div><h3>${esc(a[0])}</h3><p>${esc(a[1])}</p><div class="xp-ai"><span class="xp-ai-label"><span class="xp-spark" aria-hidden="true">✦</span>${esc(c.xpAiLabel)}</span><ol class="xp-agents">${c.xpAgents[i].map((g,j)=>`<li style="--j:${j}">${esc(g)}</li>`).join('')}</ol><p>${esc(a[2])}</p></div><div class="xp-kw">${esc(a[3])}</div></article>`).join('');document.querySelector('#towerFacts').innerHTML=c.towerFacts.map(f=>`<li><strong>${esc(f[0])}</strong><span>${esc(f[1])}</span></li>`).join('');
document.querySelector('#gateNodes').innerHTML=c.gates.map((g,i)=>`<circle class="gate-node" style="--d:${i*0.35}s" cx="60" cy="${40+i*60}" r="9"/>`).join('')+`<circle class="gate-end" cx="250" cy="520" r="11"/><circle class="gate-end hold" cx="250" cy="250" r="9"/>`;
document.querySelector('#gateLabels').innerHTML=c.gates.map((g,i)=>`<span class="gate-label" style="top:${(40+i*60)/5.6}%;--d:${i*0.35}s">${String(i+1).padStart(2,'0')} · ${esc(g)}</span>`).join('')+`<span class="gate-label hold" style="top:${250/5.6}%">${esc(c.gateHold)}</span><span class="gate-label human" style="top:${520/5.6}%">${esc(c.gateHuman)}</span>`;
document.querySelector('#prinGrid').innerHTML=c.principles.map(p=>`<div class="principle"><span class="asterisk">✳</span><h3>${esc(p[0])}</h3><p>${esc(p[1])}</p></div>`).join('');}
function tabs(sel,attr,set){document.querySelectorAll(sel).forEach(b=>b.addEventListener('click',()=>{set(b.dataset[attr]);document.querySelectorAll(sel).forEach(t=>{t.classList.toggle('active',t===b);t.setAttribute('aria-selected',String(t===b))});render()}))}
document.querySelector('#language').addEventListener('click',e=>{const b=e.target.closest('[data-lang]');if(!b||b.dataset.lang===lang)return;lang=b.dataset.lang;try{localStorage.setItem('gaia_lang',lang)}catch(e){}render()});tabs('.eco-tab','tab',v=>activeTab=v);tabs('.use-tab','use',v=>activeUse=v);document.querySelector('#menuToggle').addEventListener('click',()=>{let e=document.querySelector('#mobileNav');e.classList.toggle('show');document.querySelector('#menuToggle').setAttribute('aria-expanded',String(e.classList.contains('show')))});document.querySelectorAll('.mobile-nav a').forEach(a=>a.addEventListener('click',()=>document.querySelector('#mobileNav').classList.remove('show')));document.querySelector('#contactForm').addEventListener('submit',async e=>{e.preventDefault();const f=e.target,c=content[lang],st=document.querySelector('#formStatus'),btn=document.querySelector('#composeMail');if(f._honey.value)return;const email=f.email.value.trim(),msg=f.message.value.trim();if(!msg||!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)){st.className='form-status err';st.textContent=c.cfMissing;return}const to=['contact@gaiapath.ai','mehrzad@gaiapath.ai','support@gaiapath.ai'].includes(f.to.value)?f.to.value:'contact@gaiapath.ai';btn.disabled=true;st.className='form-status';st.textContent=c.cfSending;try{const r=await fetch('https://formsubmit.co/ajax/'+to,{method:'POST',headers:{'Content-Type':'application/json',Accept:'application/json'},body:JSON.stringify({email,_replyto:email,message:msg,_subject:'GAIA PATH Website – '+email,_template:'table',_captcha:'false'})});const d=await r.json().catch(()=>({}));if(!r.ok||String(d.success)==='false'){const m=String(d.message||r.status);if(/activat/i.test(m)){st.className='form-status err';st.textContent=c.cfAct.replace('%s',to);return}throw new Error(m)}st.className='form-status ok';st.textContent=c.cfOk;f.reset()}catch(err){st.className='form-status err';st.textContent=c.cfErr+' ('+(err&&err.message||'network')+')'}finally{btn.disabled=false}});document.querySelector('#year').textContent=new Date().getFullYear();render();

// Scroll reveal: fade content in as it enters the viewport; the decision-path drawings animate once visible
(function(){const sel='.section-top,.intro h2,.intro-side,.problem-card,.step,.cap-card,.area-row,.service-card,.principle,.tower-copy,.tower-visual,.cycle-path,.nature-ecosystem-story article,.about-copy,.about-picture,.pub-card,.eco-diagram,.brief-doc,.xp-card';
if(!('IntersectionObserver' in window)||matchMedia('(prefers-reduced-motion: reduce)').matches){document.documentElement.classList.add('no-anim');return}
document.documentElement.classList.add('anim');const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in');io.unobserve(e.target)}}),{threshold:.15});
const watch=()=>document.querySelectorAll(sel).forEach((n,i)=>{if(!n.classList.contains('in')){n.style.setProperty('--stagger',(i%4)*0.08+'s');io.observe(n)}});watch();document.getElementById('language').addEventListener('click',()=>setTimeout(watch,0));document.querySelectorAll('.use-tab').forEach(b=>b.addEventListener('click',()=>setTimeout(()=>document.querySelectorAll('.area-row').forEach(n=>n.classList.add('in')),0)))})();

(function(){const stage=document.getElementById('filmStage'),bars=document.getElementById('filmBars'),btn=document.getElementById('filmToggle');if(!stage)return;const DUR=5200;let i=0,timer=null,visible=false,paused=false;const still=matchMedia('(prefers-reduced-motion: reduce)').matches;
function show(n){const s=stage.children,b=bars.children;if(!s.length)return;i=(n+s.length)%s.length;[...s].forEach((e,k)=>e.classList.toggle('active',k===i));[...b].forEach((e,k)=>{e.classList.toggle('done',k<i);e.classList.remove('run');if(k===i){void e.offsetWidth;e.classList.add('run')}})}
function tick(){clearTimeout(timer);if(visible&&!paused){timer=setTimeout(()=>{show(i+1);tick()},DUR)}stage.parentNode.classList.toggle('paused',!visible||paused)}
window.filmRender=c=>{stage.innerHTML=c.film.map((f,k)=>`<figure class="film-slide${k===i?' active':''}"><img src="assets/${f[0]}.jpg" alt="" loading="lazy" decoding="async"><figcaption><span class="film-no">${String(k+1).padStart(2,'0')} / ${String(c.film.length).padStart(2,'0')} · ${esc(f[2])}</span><span class="film-cap">${f[3]}</span><a class="film-more" href="#${f[1]}" data-film-target="${f[1]}" tabindex="${k===i?0:-1}">${esc(c.filmMore)} →</a></figcaption></figure>`).join('');bars.innerHTML=c.film.map((f,k)=>`<button type="button" aria-label="${k+1}"></button>`).join('');[...bars.children].forEach((b,k)=>b.addEventListener('click',()=>{show(k);tick()}));show(i)};
btn.addEventListener('click',()=>{paused=!paused;btn.textContent=paused?'▶':'❚❚';btn.setAttribute('aria-label',paused?'Play':'Pause');tick()});
if(still)paused=true,btn.textContent='▶';
if('IntersectionObserver' in window){new IntersectionObserver(es=>{visible=es[0].isIntersecting;tick()},{threshold:.35}).observe(stage.parentNode)}else{visible=true;tick()}
if(typeof content!=='undefined')filmRender(content[lang]);})();

document.addEventListener('click',e=>{const a=e.target.closest&&e.target.closest('[data-film-target]');if(!a)return;e.preventDefault();const id=a.dataset.filmTarget,el=document.getElementById(id);if(!el)return;const k=id.startsWith('eco-')&&id.slice(4);if(k){const b=document.querySelector('.eco-tab[data-tab="'+k+'"]');if(b)b.click()}el.classList.add('in');el.scrollIntoView({behavior:'smooth',block:'center'});el.classList.remove('film-hit');void el.offsetWidth;el.classList.add('film-hit');setTimeout(()=>el.classList.remove('film-hit'),2600)});

(function(){const a=document.getElementById('filmAudio'),b=document.getElementById('filmSound');if(!a||!b)return;let on=false,fadeT=null;
const label=()=>{const c=content[lang];b.querySelector('[data-i]').textContent=on?c.soundOff:c.soundOn;b.setAttribute('aria-pressed',String(on));b.classList.toggle('on',on)};
const fade=(to,done)=>{clearInterval(fadeT);fadeT=setInterval(()=>{const v=a.volume+(to>a.volume?.05:-.05);if(Math.abs(to-a.volume)<=.05){a.volume=to;clearInterval(fadeT);done&&done()}else a.volume=Math.max(0,Math.min(1,v))},60)};
b.addEventListener('click',()=>{on=!on;if(on){a.volume=0;const p=a.play();if(p&&p.catch)p.catch(()=>{on=false;label()});fade(.55)}else fade(0,()=>a.pause());label()});
document.getElementById('language').addEventListener('click',()=>setTimeout(label,0));
if('IntersectionObserver' in window)new IntersectionObserver(es=>{if(!on)return;if(es[0].isIntersecting){a.play().catch(()=>{});fade(.55)}else fade(0,()=>a.pause())},{threshold:.2}).observe(document.getElementById('home'));})();

(function(){const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;let t=0;setInterval(()=>{if(reduce)return;t++;const c=content[lang];document.querySelectorAll('.xp-hud').forEach(h=>{const i=+h.dataset.hud,list=c.xpHud[i];const v=list[(t+i)%list.length];h.classList.remove('typing');void h.offsetWidth;h.textContent=v;h.classList.add('typing')})},2600);
const cv=document.getElementById('xpMesh');if(!cv||reduce)return;const ctx=cv.getContext('2d');let W,H,P=[],run=false,mx=-999,my=-999;const DPR=Math.min(2,window.devicePixelRatio||1);
function size(){const r=cv.getBoundingClientRect();W=r.width;H=r.height;cv.width=W*DPR;cv.height=H*DPR;ctx.setTransform(DPR,0,0,DPR,0,0);const N=Math.round(Math.min(90,W*H/14000));P=[];for(let i=0;i<N;i++)P.push({x:Math.random()*W,y:Math.random()*H,vx:(Math.random()-.5)*.35,vy:(Math.random()-.5)*.35,g:Math.random()<.12})}
const pulses=[];function frame(){if(!run)return;ctx.clearRect(0,0,W,H);for(const p of P){p.x+=p.vx;p.y+=p.vy;if(p.x<0||p.x>W)p.vx*=-1;if(p.y<0||p.y>H)p.vy*=-1;const dx=p.x-mx,dy=p.y-my,d=Math.hypot(dx,dy);if(d<120){p.x+=dx/d*.6;p.y+=dy/d*.6}}
for(let i=0;i<P.length;i++)for(let j=i+1;j<P.length;j++){const a=P[i],b=P[j],d=Math.hypot(a.x-b.x,a.y-b.y);if(d<140){ctx.strokeStyle=`rgba(117,164,160,${(1-d/140)*.35})`;ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke();if(Math.random()<.0009&&pulses.length<26)pulses.push({a,b,t:0})}}
for(let k=pulses.length-1;k>=0;k--){const q=pulses[k];q.t+=.018;if(q.t>=1){pulses.splice(k,1);continue}const x=q.a.x+(q.b.x-q.a.x)*q.t,y=q.a.y+(q.b.y-q.a.y)*q.t;const gr=ctx.createRadialGradient(x,y,0,x,y,10);gr.addColorStop(0,'rgba(243,213,143,.95)');gr.addColorStop(1,'rgba(209,166,84,0)');ctx.fillStyle=gr;ctx.beginPath();ctx.arc(x,y,10,0,6.3);ctx.fill()}
for(const p of P){ctx.fillStyle=p.g?'rgba(209,166,84,.95)':'rgba(232,238,240,.55)';ctx.beginPath();ctx.arc(p.x,p.y,p.g?2.6:1.5,0,6.3);ctx.fill()}requestAnimationFrame(frame)}
size();addEventListener('resize',size);const host=cv.parentNode;host.addEventListener('pointermove',e=>{const r=cv.getBoundingClientRect();mx=e.clientX-r.left;my=e.clientY-r.top});host.addEventListener('pointerleave',()=>{mx=my=-999});
new IntersectionObserver(es=>{const v=es[0].isIntersecting;if(v&&!run){run=true;size();requestAnimationFrame(frame)}else if(!v)run=false}).observe(host)})();
